CREATE TABLE `planes_estudio` (
  `id_plan` int(11) NOT NULL,
  `id_carrera` int(11) NOT NULL,
  `version` varchar(20) NOT NULL,
  `nombre_plan` varchar(100) NOT NULL,
  `duracion_cuatrimestres` int(11) NOT NULL,
  `fecha_vigencia_inicio` date NOT NULL,
  `estatus` enum('Borrador','Vigente','Cerrado','Reemplazado') NOT NULL DEFAULT 'Borrador'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `planes_estudio`
--

INSERT INTO `planes_estudio` (`id_plan`, `id_carrera`, `version`, `nombre_plan`, `duracion_cuatrimestres`, `fecha_vigencia_inicio`, `estatus`) VALUES
(1, 1, '2018-1', 'Plan tic 2018', 11, '2022-09-05', 'Vigente'),
(2, 2, '2025-1', 'PLAN 2025', 10, '2026-08-20', 'Cerrado'),
(3, 3, '2025-1', 'PLAN 2025', 10, '2026-08-20', 'Vigente'),
(4, 4, '2025-1', 'PLAN 2025', 10, '2026-08-20', 'Vigente');

--
-- Disparadores `planes_estudio`
--
DELIMITER $$
CREATE TRIGGER `trg_planes_bloquear_vigente_directo` BEFORE INSERT ON `planes_estudio` FOR EACH ROW BEGIN
    IF NEW.estatus = 'Vigente' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Un plan debe crearse en Borrador; solo puede marcarse Vigente despues de registrar al menos un nivel academico.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_planes_bloquear_vigente_sin_niveles` BEFORE UPDATE ON `planes_estudio` FOR EACH ROW BEGIN
    IF NEW.estatus = 'Vigente' AND OLD.estatus <> 'Vigente' THEN
        IF (SELECT COUNT(*) FROM `plan_niveles` WHERE id_plan = NEW.id_plan) = 0 THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'No se puede marcar como Vigente un plan sin niveles academicos asignados.';
        END IF;
    END IF;
END
$$
DELIMITER ;

