--
-- Disparadores `plan_niveles`
--
DELIMITER $$
CREATE TRIGGER `trg_plan_niveles_evitar_dejar_sin_nivel` BEFORE DELETE ON `plan_niveles` FOR EACH ROW BEGIN
    DECLARE tramos_restantes INT;

    SELECT COUNT(*) INTO tramos_restantes
    FROM `plan_niveles`
    WHERE `id_plan` = OLD.`id_plan`;

    IF tramos_restantes <= 1 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Un plan de estudios siempre debe conservar al menos un nivel académico.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_plan_niveles_no_vaciar_vigente` BEFORE DELETE ON `plan_niveles` FOR EACH ROW BEGIN
    DECLARE estatus_plan VARCHAR(20);
    DECLARE niveles_restantes INT;

    SELECT estatus INTO estatus_plan FROM `planes_estudio` WHERE id_plan = OLD.id_plan;
    SELECT COUNT(*) INTO niveles_restantes FROM `plan_niveles` WHERE id_plan = OLD.id_plan;

    IF estatus_plan = 'Vigente' AND niveles_restantes <= 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Un plan Vigente no puede quedarse sin niveles academicos; cierra el plan si ya no aplica.';
    END IF;
END
$$
DELIMITER ;

