--
-- Disparadores `trayectorias_academicas`
--
DELIMITER $$
CREATE TRIGGER `trg_trayectoria_valida_avance` BEFORE INSERT ON `trayectorias_academicas` FOR EACH ROW BEGIN
    DECLARE estado_anterior VARCHAR(20);
    DECLARE materias_pendientes INT;

    IF NEW.id_trayectoria_anterior IS NOT NULL THEN
        SELECT estado INTO estado_anterior
        FROM trayectorias_academicas
        WHERE id_trayectoria = NEW.id_trayectoria_anterior;

        IF estado_anterior IS NULL THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'La trayectoria anterior indicada no existe.';
        ELSEIF estado_anterior <> 'ACTIVA' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'La trayectoria anterior ya no esta activa; no se puede encadenar un avance de nivel desde ella.';
        END IF;

        SELECT COUNT(*) INTO materias_pendientes
        FROM materias m
        JOIN plan_cuatrimestres pc
            ON m.id_plan_cuatrimestre = pc.id_plan_cuatrimestre
        JOIN plan_niveles pn
            ON pn.id_plan = pc.id_plan
           AND pc.numero_cuatrimestre BETWEEN pn.cuatrimestre_inicio AND pn.cuatrimestre_fin
        WHERE pc.id_plan = (
                SELECT id_plan
                FROM trayectorias_academicas
                WHERE id_trayectoria = NEW.id_trayectoria_anterior
              )
          AND pn.cuatrimestre_inicio = (
                SELECT MIN(pn2.cuatrimestre_inicio)
                FROM plan_niveles pn2
                WHERE pn2.id_plan = pc.id_plan
                  AND pn2.cuatrimestre_fin >= COALESCE((
                        SELECT MAX(pc2.numero_cuatrimestre)
                        FROM inscripciones i2
                        JOIN grupos g2
                            ON i2.id_grupo = g2.id_grupo
                        JOIN plan_cuatrimestres pc2
                            ON g2.id_plan_cuatrimestre = pc2.id_plan_cuatrimestre
                        WHERE i2.id_trayectoria = NEW.id_trayectoria_anterior
                          AND i2.estado = 'Activa'
                      ), 1)
              )
          AND m.estatus = 'Activa'
          AND NOT EXISTS (
                SELECT 1
                FROM inscripcion_materias im
                JOIN grupo_materias gm
                    ON im.id_grupo_materia = gm.id_grupo_materia
                JOIN inscripciones i
                    ON im.id_inscripcion = i.id_inscripcion
                WHERE gm.id_materia = m.id_materia
                  AND i.id_trayectoria = NEW.id_trayectoria_anterior
                  AND im.estado = 'Aprobada'
              );

        IF materias_pendientes > 0 THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'El alumno no puede avanzar de nivel: tiene materias del tramo actual sin aprobar.';
        END IF;
    END IF;
END
$$
DELIMITER ;

